import React from 'react';

function Register() {
  const handleSubmit = (e) => {
    e.preventDefault();
    alert('form');
  };
  return (
    <>
      <form onSubmit={(e) => handleSubmit(e)}>
        <div className="logo">
          <img src="" alt="" />
          <h2>chaxapp</h2>
        </div>
        <div className="input_div">
          <input
            type="text"
            name="username"
            onChange={(e) => handleChange(e)}
                  />
        <label></label>
        </div>
      </form>
    </>
  );
}

export default Register;
